files.content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: #1a1a2e;
  color: #e0e0e0;
  font-family: system-ui, -apple-system, sans-serif;
  font-size: 16px;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
}

.card {
  background: #16213e;
  border-radius: 16px;
  padding: 24px;
  max-width: 600px;
  width: 100%;
  box-shadow: 0 8px 24px rgba(0,0,0,0.4);
}

h1 {
  font-size: 24px;
  margin-bottom: 16px;
  color: #e94560;
  text-align: center;
}

.controls {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  align-items: center;
  margin-bottom: 20px;
  justify-content: center;
}

button, input {
  font-size: 16px;
  padding: 8px 16px;
  border-radius: 8px;
  border: 2px solid #0f3460;
  background: #0f3460;
  color: #e0e0e0;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s;
}

button:hover, input:hover {
  background: #1a4a7a;
  border-color: #e94560;
}

button:focus-visible, input:focus-visible {
  outline: 3px solid #e94560;
  outline-offset: 2px;
}

button:active {
  background: #e94560;
  transform: scale(0.97);
}

button.active {
  background: #e94560;
  border-color: #e94560;
}

input[type="number"] {
  width: 80px;
  text-align: center;
}

label {
  font-size: 16px;
}

.grid {
  display: grid;
  grid-template-columns: repeat(8, 1fr);
  gap: 6px;
}

.step {
  aspect-ratio: 1;
  border-radius: 6px;
  border: 2px solid #0f3460;
  background: #0a0a1a;
  cursor: pointer;
  transition: background 0.1s, border-color 0.1s;
  padding: 0;
}

.step:hover {
  border-color: #e94560;
}

.step:focus-visible {
  outline: 3px solid #e94560;
  outline-offset: 2px;
}

.step.active {
  background: #e94560;
  border-color: #e94560;
}

.step.playhead {
  border-color: #e0e0e0;
  box-shadow: 0 0 8px #e0e0e0;
}

.instrument-label {
  grid-column: span 8;
  font-size: 14px;
  font-weight: bold;
  color: #e94560;
  margin-top: 8px;
  text-align: left;
}

.instrument-label:first-child {
  margin-top: 0;
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
  }
  .grid {
    gap: 4px;
  }
  .controls {
    gap: 8px;
  }
  button, input {
    padding: 6px 12px;
    font-size: 14px;
  }
}

const ROWS = 4;
const COLS = 8;
const INSTRUMENTS = ['Kick', 'Snare', 'Hi-Hat', 'Clap'];

const state = Array.from({ length: ROWS }, () => Array(COLS).fill(false));
let playing = false;
let currentCol = -1;
let timerId = null;

const gridEl = document.getElementById('grid');
const playBtn = document.getElementById('playBtn');
const clearBtn = document.getElementById('clearBtn');
const bpmInput = document.getElementById('bpmInput');

function buildGrid() {
  gridEl.innerHTML = '';
  for (let r = 0; r < ROWS; r++) {
    const label = document.createElement('div');
    label.className = 'instrument-label';
    label.textContent = INSTRUMENTS[r];
    gridEl.appendChild(label);
    for (let c = 0; c < COLS; c++) {
      const cell = document.createElement('button');
      cell.className = 'step';
      cell.setAttribute('role', 'gridcell');
      cell.setAttribute('aria-label', `${INSTRUMENTS[r]} step ${c + 1}`);
      cell.dataset.row = r;
      cell.dataset.col = c;
      cell.addEventListener('click', () => toggleStep(r, c));
      gridEl.appendChild(cell);
    }
  }
}

function toggleStep(r, c) {
  state[r][c] = !state[r][c];
  updateCell(r, c);
}

function updateCell(r, c) {
  const cell = gridEl.querySelector(`.step[data-row="${r}"][data-col="${c}"]`);
  if (cell) cell.classList.toggle('active', state[r][c]);
}

function clearGrid() {
  for (let r = 0; r < ROWS; r++) {
    for (let c = 0; c < COLS; c++) {
      state[r][c] = false;
      updateCell(r, c);
    }
  }
}

function getBPM() {
  const val = parseInt(bpmInput.value, 10);
  return Math.min(240, Math.max(40, isNaN(val) ? 120 : val));
}

function advance() {
  if (currentCol >= 0) {
    const prev = gridEl.querySelector(`.step[data-col="${currentCol}"]`);
    if (prev) prev.classList.remove('playhead');
  }
  currentCol = (currentCol + 1) % COLS;
  for (let r = 0; r < ROWS; r++) {
    const cell = gridEl.querySelector(`.step[data-row="${r}"][data-col="${currentCol}"]`);
    if (cell) cell.classList.add('playhead');
  }
  const interval = 60000 / getBPM() / 2;
  timerId = setTimeout(advance, interval);
}

function startPlayback() {
  if (playing) return;
  playing = true;
  playBtn.textContent = 'Stop';
  playBtn.classList.add('active');
  playBtn.setAttribute('aria-label', 'Stop');
  currentCol = -1;
  advance();
}

function stopPlayback() {
  playing = false;
  clearTimeout(timerId);
  playBtn.textContent = 'Play';
  playBtn.classList.remove('active');
  playBtn.setAttribute('aria-label', 'Play');
  if (currentCol >= 0) {
    gridEl.querySelectorAll('.playhead').forEach(el => el.classList.remove('playhead'));
  }
  currentCol = -1;
}

playBtn.addEventListener('click', () => {
  if (playing) stopPlayback(); else startPlayback();
});

clearBtn.addEventListener('click', clearGrid);

bpmInput.addEventListener('change', () => {
  bpmInput.value = getBPM();
});

buildGrid();
